import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:schematic_3d/domain/formats/mapper.dart';

import '../helpers.dart';

/// Parity pin: the SAME vector file the Bedrock add-on (core/tint.js) is
/// tested against — generated by bedrock_addon/scripts/gen_tint_vectors.mjs.
/// If the Dart port drifts from the JS classification, this test fails.
void main() {
  late List<dynamic> vectors;

  setUpAll(() {
    final raw =
        File(fixture('app/assets/generated/tint_vectors.json'))
            .readAsStringSync();
    vectors = jsonDecode(raw) as List<dynamic>;
    expect(vectors.isNotEmpty, isTrue);
  });

  test('golden tint vectors match the Dart port', () {
    final mismatches = <String>[];
    for (final v in vectors) {
      final id = (v as Map<String, Object?>)['id'].toString();
      final expected = v['tint'];
      final actual = Mapper.ghostTintFor(id);
      if (expected.toString() != (actual ?? 'null')) {
        mismatches.add('$id: want $expected got $actual');
      }
    }
    expect(mismatches, isEmpty,
        reason: 'tint drift vs add-on (${mismatches.length} of '
        '${vectors.length})');
  });

  test('ghostBlockId prefixes s3d: and nulls air', () {
    expect(Mapper.ghostBlockId('minecraft:air'), isNull);
    expect(Mapper.ghostBlockId('minecraft:structure_void'), isNull);
    expect(Mapper.ghostBlockId('minecraft:oak_planks'), 's3d:ghost_wood');
  });
}
